head.script:
scwin.onpageload = function () {
    console.log(button1.getLabel());
};

scwin.button2_onclick = function (e) {
    button1.setLabel("label 값 변경");
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('button1').value == 'label 값 변경';
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
